<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $editing = !empty($record['id']); ?>
<section><p class="eyebrow">Arbitragem</p><h1><?= $editing ? 'Editar cadastro' : 'Novo árbitro ou oficial' ?></h1><?php foreach ($errors as $error): ?><p class="alert"><?= $e($error) ?></p><?php endforeach; ?><form method="post" enctype="multipart/form-data" action="<?= $e(App\Core\Config::url($editing ? '/admin/arbitros/' . $record['id'] : '/admin/arbitros')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Campeonato <select name="championship_id" required><option value="">Selecione</option><?php foreach ($championships as $championship): ?><option value="<?= $championship['id'] ?>" <?= (int) ($record['championship_id'] ?? 0) === (int) $championship['id'] ? 'selected' : '' ?>><?= $e($championship['name']) ?></option><?php endforeach; ?></select></label><label>Nome completo <input name="full_name" value="<?= $e($record['full_name'] ?? '') ?>" required></label><label>Nome público <input name="public_name" value="<?= $e($record['public_name'] ?? '') ?>" placeholder="Opcional"></label><label>Função <select name="role"><?php foreach (['referee' => 'Árbitro', 'assistant' => 'Assistente', 'fourth_official' => 'Quarto oficial', 'scorekeeper' => 'Mesário', 'coordinator' => 'Coordenador'] as $key => $label): ?><option value="<?= $key ?>" <?= ($record['role'] ?? '') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Foto <input type="file" name="photo" accept=".png,.jpg,.jpeg,.webp"></label><label>Status <select name="status"><option value="active" <?= ($record['status'] ?? '') === 'active' ? 'selected' : '' ?>>Ativo</option><option value="inactive" <?= ($record['status'] ?? '') === 'inactive' ? 'selected' : '' ?>>Inativo</option></select></label><button type="submit">Salvar cadastro</button></form></section>
